'use strict';
// Tray / menu-bar icon that follows the selected pet (generated by npm run icons).
const path = require('node:path'), fs = require('node:fs');
const PET_IDS = ['cat', 'chick', 'bunny', 'bear', 'fox'];
const normalize = (id) => PET_IDS.includes(id) ? id : 'cat';
// macOS loads `<id>Template.png` and picks up `@2x` automatically; the
// "Template" suffix lets the menu bar tint it for light / dark.
function trayIconPath(petId, platform = process.platform, base = path.join(__dirname, 'assets', 'tray')) {
  const id = normalize(petId);
  if (platform === 'darwin') return path.join(base, `${id}Template.png`);
  if (platform === 'win32') return path.join(base, `${id}.ico`);
  return path.join(base, `${id}.png`);
}
function createTrayPet({ getTray, nativeImage, getWindow = () => null, app = null, directory = '', platform = process.platform }) {
  const file = directory && path.join(directory, 'pet-identity.json');
  let current = 'cat';
  if (file) { try { current = normalize(JSON.parse(fs.readFileSync(file, 'utf8')).petId); } catch {} }
  return {
    get petId() { return current; },
    // Internal: called whenever the companion snapshot reports a pet.
    setTrayPet(petId) {
      const id = normalize(petId); if (id === current && getTray()?.__petId === id) return false;
      if (file && id !== current) { fs.mkdirSync(directory, { recursive: true }); fs.writeFileSync(file + '.tmp', JSON.stringify({ version: 1, petId: id }), { mode: 0o600 }); fs.renameSync(file + '.tmp', file); }
      current = id;
      const full = nativeImage.createFromPath(path.join(__dirname, 'assets', 'tray', `${id}.png`));
      if (!full.isEmpty()) {
        if (platform === 'darwin') app?.dock?.setIcon(full);
        const win = getWindow(); if (platform === 'win32' && win && !win.isDestroyed()) win.setIcon(full);
      }
      const tray = getTray(); if (!tray) return true;
      const image = nativeImage.createFromPath(trayIconPath(id, platform));
      if (platform === 'darwin') image.setTemplateImage?.(true);
      if (!image.isEmpty()) { tray.setImage(image); tray.__petId = id; }
      return true;
    }
  };
}
module.exports = { trayIconPath, createTrayPet, PET_IDS };
